import ast,sys
for f in ['main','native','protocol','fib','layout','planner']:
    src=open('/workspace/submission/%s.py'%f).read()
    tree=ast.parse(src)
    imports=set()
    for n in ast.walk(tree):
        if isinstance(n,ast.Import): imports|={a.asname or a.name.split('.')[0] for a in n.names}
        elif isinstance(n,ast.ImportFrom): imports|={(a.asname or a.name) for a in n.names}
    used=set()
    for n in ast.walk(tree):
        if isinstance(n,ast.Name): used.add(n.id)
        if isinstance(n,ast.Attribute): pass
    txt=src
    unused=[i for i in imports if txt.count(i)<2]
    print(f,'unused imports:',unused)
